import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Projects Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Projects Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/projects-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Projects Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/projects-overview"}]]},"headers":[],"relativePath":"user-guide/projects-overview.md","filePath":"user-guide/projects-overview.md","lastUpdated":1788612600000}'),s={name:"user-guide/projects-overview.md"};function n(d,e,i,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="projects-module" tabindex="-1">Projects Module <a class="header-anchor" href="#projects-module" aria-label="Permalink to &quot;Projects Module&quot;">​</a></h1><p>Lean Operations module on the frozen platform. Plan and track workspace projects with a primary assignee, optional members, status board, notes/timeline, and <strong>soft, optional</strong> Contact / Company / Opportunity links. Tasks may optionally set <code>project_id</code> when Projects is entitled (Tasks catalog <strong>1.2.0</strong>).</p><p>Projects is <strong>standalone</strong>: it installs with no hard <code>module_dependencies</code>, and works fully on its own.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/projects">projects.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/projects">projects.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/projects">projects.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Related</td><td><a href="/user-guide/tasks-overview">Tasks</a> · <a href="/user-guide/opportunities-overview">Opportunities</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-projects">../api/tenant-v1-projects.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Fields: <strong><code>title</code></strong> (required — not <code>name</code>), optional description, <code>starts_on</code> / <code>ends_on</code> (date), status, assignee, members</li><li>Status workflow: <code>planned → active|cancelled</code>; <code>active → on_hold|completed|cancelled</code>; <code>on_hold → active|cancelled</code> (<code>completed</code> / <code>cancelled</code> terminal)</li><li>Members + assignee; visibility without <code>projects.assign</code> = assignee <strong>OR</strong> member <strong>OR</strong> creator</li><li>Soft optional Contact / Company / Opportunity links (validated only when that module is entitled)</li><li>Soft Task <code>project_id</code> (Tasks → Projects optional; Tasks catalog <strong>1.1.2 → 1.2.0</strong>)</li><li>Board + stats + notes/timeline</li><li><strong>Calendar projection</strong> — all-day events on <code>starts_on</code> / <code>ends_on</code> (assignee as organizer); cancelled projects cancel/remove projection</li><li>Dashboard widgets: <code>active_projects</code>, <code>overdue_projects</code></li><li>Overdue uses workspace <strong>Timezone</strong> calendar “today” vs <code>ends_on</code> (open statuses only)</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:projects</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong>, no hard dependencies</li><li>Audit + activity logging; assignee and new-member notifications</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>projects.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code></p><p>Enable Projects from Marketplace (free). Catalog: slug <code>projects</code>, category <code>operations</code> (Operations), version <strong>1.2.0</strong>, <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 10</code>. Nav: <strong>Workspace</strong> group, after Tasks.</p><h2 id="why-standalone-soft-dependencies" tabindex="-1">Why standalone (soft dependencies) <a class="header-anchor" href="#why-standalone-soft-dependencies" aria-label="Permalink to &quot;Why standalone (soft dependencies)&quot;">​</a></h2><p>Contact, Company, and Opportunity links are optional cross-references — a project can be pure internal work with no CRM deal behind it. Tasks may link to a project only when Projects is entitled (<code>LinkableProject</code>); uninstalling Projects nulls the FK rather than blocking Tasks.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Gantt charts</li><li>Milestones</li><li>Task dependencies</li><li>Workload heatmaps</li><li>Automation <code>create_project</code> action</li><li>Project tags</li><li>Human-readable <code>PRJ-</code> numbers</li></ul>',14)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
